<script lang="ts">
 import {onMount} from 'svelte';
 import RuntimeConsole from '$lib/components/RuntimeConsole.svelte';
 import {PUBLIC_CONVEX_URL} from '$env/static/public';
 import {authenticatedClient,functionRef,sessionRequest,controlQuery,controlMutation} from '$lib/admin';
 import type {ConvexClient} from 'convex/browser';
 const sections=['Analytics','Applications','Referrals','Financial','Users','Settings'];
 const schemas:Record<string,string[]>={applications:['name','email','type','status','notes'],referrals:['code','email','referredBy','status'],financial:['reference','type','amount','currency','status','notes'],users:['subject','email','name','status'],settings:['key','value','description']};
 let section=$state('Analytics'),drawer=$state(false),user:any=$state(null),ready=$state(false),error=$state(''),notice=$state(''),overview:any=$state(null),rows:any[]=$state([]),busy=$state(false),editing:any=$state(null),dialog:HTMLDialogElement,form:Record<string,string>=$state({}),cursor:string|null=$state(null),next:string|null=$state(null),done=$state(true);
 let client:ConvexClient|undefined,stopRows:(()=>void)|undefined,stopOverview:(()=>void)|undefined;
 const key=()=>section.toLowerCase();
 function watch(){stopRows?.();rows=[];cursor=null;if(section==='Analytics'||!ready)return;subscribe();}
 async function subscribe(){try{const selected=key();const data=await controlQuery('admin-list',{section:selected,cursor});if(selected!==key())return;rows=data.page;next=data.continueCursor;done=data.isDone;}catch(e){error=e instanceof Error?e.message:String(e);}}
 function choose(s:string){section=s;drawer=false;error='';watch();}
 function open(record:any=null){editing=record;form=Object.fromEntries((schemas[key()]??[]).map(k=>[k,String(record?.[k]??'')]));dialog.showModal();}
 async function save(e:SubmitEvent){e.preventDefault();if(!ready)return;busy=true;error='';try{const data:Record<string,unknown>={...form};if('amount' in data){data.amount=Number(data.amount);if(!Number.isFinite(data.amount))throw new Error('Enter a valid amount');}await controlMutation('admin:save',{section:key(),...(editing?{id:editing._id}:{}),data});await subscribe();overview=await controlQuery('admin-overview');dialog.close();notice='Record saved. The snapshot is refreshed.';}catch(e){error=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 async function remove(row:any){if(!ready||!confirm(`Delete ${row.name??row.code??row.key??row.email??'this record'}? This action is audited.`))return;busy=true;try{await controlMutation('admin:remove',{section:key(),id:row._id});await subscribe();overview=await controlQuery('admin-overview');notice='Record deleted.';}catch(e){error=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 async function signout(){try{await sessionRequest('/api/auth/logout',{method:'POST'});location.assign('/login');}catch(e){error=e instanceof Error?e.message:String(e);}}
 onMount(()=>{let disposed=false;(async()=>{try{const session=await sessionRequest('/api/auth/session');if(disposed)return;user=session.user;if(!user||!['admin','super_admin'].includes(user.role))throw new Error('Administrator access is required. Sign in with an authorized account.');if(!PUBLIC_CONVEX_URL)throw new Error('Production backend is not configured.');overview=await controlQuery('admin-overview');ready=true;}catch(e){error=e instanceof Error?e.message:String(e);}})();return()=>{disposed=true;stopRows?.();stopOverview?.();void client?.close();};});
</script>
<svelte:head><title>Operations console · OmieBot AI Trading</title><meta name="robots" content="noindex,nofollow"/></svelte:head>
<div class="console"><header><a class="brand" href="/">Omie<span>Bot</span><small>AI TRADING / OPERATIONS</small></a><button class="menu" aria-expanded={drawer} aria-controls="admin-nav" onclick={()=>drawer=!drawer}>☰ <span>Menu</span></button><div class="account"><span>{user?.email??'Secure workspace'}</span><a href="/">Open terminal ↗</a>{#if ready}<button onclick={signout}>Sign out</button>{:else}<a href="/login">Sign in →</a>{/if}</div></header><div class="body"><aside id="admin-nav" class:open={drawer}><p>MANAGEMENT</p>{#each sections as s,i}<button class:active={section===s} onclick={()=>choose(s)}><span>0{i+1}</span>{s}</button>{/each}<div class="side-note"><strong>Guardian controlled</strong><p>Server permissions, audit trails and quota gates protect every operation.</p></div></aside><main><div class="heading"><div><span class="eyebrow">OMIEBOT CONTROL CENTER</span><h1>{section}</h1><p>One workspace. Verified records. Clear operational evidence.</p></div>{#if ready&&section!=='Analytics'}<button class="primary" onclick={()=>open()}>+ {section==='Financial'?'Append financial record':'Create record'}</button>{/if}</div>{#if error}<div class="alert" role="alert">{error}</div>{/if}{#if notice}<div class="notice" role="status">{notice}<button aria-label="Dismiss notification" onclick={()=>notice=''}>×</button></div>{/if}{#if !ready}<section class="card empty"><h2>Secure administrator workspace</h2><p>{error?'Access has not been established.':'Verifying your session…'}</p><a href="/login">Continue to sign in →</a></section>{:else if section==='Analytics'}<div class="metrics">{#each Object.entries(overview?.counts??{}) as [label,value]}<article class="card"><span>{label}</span><strong>{String(value)}</strong><small>{overview?.countsCapped?'Bounded operational count':'Live backend count'}</small></article>{:else}<article class="card"><span>Backend analytics</span><strong>—</strong><small>Waiting for authenticated data</small></article>{/each}</div><RuntimeConsole/><section class="card"><h2>Audit trail</h2><div class="table-wrap"><table><thead><tr><th>Time</th><th>Action</th><th>Actor</th></tr></thead><tbody>{#each overview?.audit??[] as row}<tr><td>{new Date(row.at??row._creationTime).toLocaleString()}</td><td>{row.action}</td><td>{row.actor??row.email??'Server'}</td></tr>{:else}<tr><td colspan="3">No audit records returned.</td></tr>{/each}</tbody></table></div></section>{:else}<section class="card records"><div class="card-title"><h2>{section} records</h2><span class="badge">ON-DEMAND SNAPSHOT</span></div>{#if section==='Financial'}<p>Financial records are append only. Trade fills and reconciliation evidence cannot be edited or deleted through this console. A record does not establish settled funds.</p>{:else if section==='Settings'}<p>Operational settings only. Provider secrets are never displayed here. Provider hard limits are enforced independently by the runtime.</p>{/if}<div class="table-wrap"><table><thead><tr>{#each schemas[key()]??[] as field}<th>{field}</th>{/each}{#if section!=='Financial'}<th>Actions</th>{/if}</tr></thead><tbody>{#each rows as row}<tr>{#each schemas[key()]??[] as field}<td>{String(row[field]??'—')}</td>{/each}{#if section!=='Financial'}<td class="actions"><button onclick={()=>open(row)}>Edit</button><button class="danger" disabled={busy} onclick={()=>remove(row)}>Delete</button></td>{/if}</tr>{:else}<tr><td colspan={(schemas[key()]?.length??0)+1}>No records on this page. Create a record to get started.</td></tr>{/each}</tbody></table></div><div class="pagination"><button disabled={!cursor} onclick={()=>{cursor=null;subscribe();}}>First page</button><span>Up to 25 records per page</span><button disabled={done} onclick={()=>{cursor=next;subscribe();}}>Next page →</button></div></section>{/if}<footer>OmieBot AI Trading <span>Evidence before execution · least privilege by design</span></footer></main></div></div>
<dialog bind:this={dialog}><form onsubmit={save}><div class="card-title"><h2>{editing?'Edit':'Create'} {key()} record</h2><button type="button" aria-label="Close record editor" onclick={()=>dialog.close()}>×</button></div>{#each schemas[key()]??[] as field}<label>{field}<input type={field==='amount'?'number':field==='email'?'email':'text'} step={field==='amount'?'any':undefined} bind:value={form[field]} maxlength="2000" required={field!=='notes'}/></label>{/each}{#if error}<p role="alert" class="danger">{error}</p>{/if}<div class="dialog-actions"><button type="button" onclick={()=>dialog.close()}>Cancel</button><button class="primary" disabled={busy}>{busy?'Saving…':'Save record'}</button></div></form></dialog>
<style>
 .console{min-height:100vh;background:#0c0f14}.console header{height:88px;display:flex;justify-content:space-between;align-items:center;padding:0 32px;border-bottom:1px solid #292e38;background:#11151c}.brand{font:700 28px 'Space Grotesk',sans-serif;letter-spacing:-1px}.brand span{color:#e6b85c}.brand small{display:block;font:8px 'DM Sans',sans-serif;letter-spacing:2.2px;margin-top:7px;color:#8a95a5}.account{display:flex;align-items:center;gap:24px;font-size:12px}.account span{color:#8995a5}.account a,.account button{color:#e6b85c}.body{display:flex}aside{width:220px;flex-shrink:0;padding:30px 16px;background:#10141b;border-right:1px solid #262d38;min-height:calc(100vh - 88px)}aside>p,.eyebrow{font-size:9px;letter-spacing:2px;color:#8a95a5}aside>p{padding:0 16px 16px}aside>button{display:flex;gap:16px;align-items:center;width:100%;padding:16px;text-align:left;border-radius:8px;color:#9ca6b5;margin-bottom:6px}aside>button span{font-size:10px;color:#626e80}aside>button.active{background:#e6b85c13;color:#e6b85c}aside>button.active span{color:#e6b85c}.side-note{border:1px solid #343129;border-radius:9px;padding:16px;margin-top:45px;font-size:11px}.side-note strong{color:#dfbc70}.side-note p{font-size:11px;line-height:1.7;color:#8994a5}main{width:calc(100% - 220px);padding:34px;min-width:0}.heading{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-bottom:30px}.eyebrow{color:#b79e67}h1{font:500 34px 'Space Grotesk',sans-serif;margin:9px 0}p{color:#8995a5;line-height:1.7}.heading p{margin:0;font-size:12px}.primary{background:#e6b85c;color:#201a10;border-radius:7px;padding:12px 17px;font-weight:650;white-space:nowrap}.card{background:#12161e;border:1px solid #2a303b;border-radius:12px;padding:22px;margin-bottom:22px}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(165px,1fr));gap:16px}.metrics article{display:grid;gap:13px}.metrics span{text-transform:uppercase;font-size:10px;color:#8e99aa;letter-spacing:1px}.metrics strong{font:500 32px 'Space Grotesk',sans-serif}.metrics small{font-size:10px;color:#6e7b8e}.card-title{display:flex;justify-content:space-between;align-items:center;gap:16px}h2{font-size:15px;font-weight:600;margin:0 0 12px}.card-title h2{margin:0}.card-title button{color:#e6b85c;font-size:11px}.card p{font-size:12px}.table-wrap{overflow:auto;margin-top:20px}table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}th{font-size:10px;text-transform:uppercase;letter-spacing:1px;color:#7d899b;font-weight:500}th,td{padding:15px 12px;border-bottom:1px solid #262c36;max-width:330px;overflow-wrap:anywhere}td{color:#b8c2d0}td:first-child{color:#e2e6ed}.actions{white-space:nowrap}.actions button{color:#e6b85c;margin-right:15px}.danger,.actions .danger{color:#f48c95}.badge{font-size:8px;letter-spacing:1px;color:#70c7aa;border:1px solid #70c7aa44;border-radius:5px;padding:6px}.pagination{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:18px;font-size:11px;color:#8390a2}.pagination button{padding:7px;color:#dfbc70}.alert,.notice{padding:15px 18px;border-radius:8px;margin:0 0 22px;line-height:1.6}.alert{background:#e76d7b12;border:1px solid #e76d7b44;color:#faa7ae}.notice{background:#67c4a612;border:1px solid #67c4a644;color:#8dd9c1;display:flex;justify-content:space-between}.empty{text-align:center;padding:50px 20px}.empty a{color:#e6b85c}footer{display:flex;justify-content:space-between;padding:15px 0;color:#68768a;font-size:10px}.menu{display:none}dialog{background:#141922;color:#e5eaf1;border:1px solid #404958;border-radius:14px;padding:26px;width:min(500px,calc(100vw - 32px));max-height:85vh}dialog::backdrop{background:#000a;backdrop-filter:blur(5px)}dialog form{display:grid;gap:17px}dialog label{display:grid;gap:7px;text-transform:capitalize;font-size:12px;color:#a9b4c3}dialog input{background:#0c1119;border:1px solid #354050;padding:12px;border-radius:7px;color:#e3e8f0;width:100%}.dialog-actions{display:flex;justify-content:flex-end;gap:22px;margin-top:10px}button,a{transition:color .15s,background .15s}button:hover,a:hover{color:#f5d495}@media(max-width:900px){.account span{display:none}main{padding:24px}aside{width:185px}main{width:calc(100% - 185px)}}@media(max-width:640px){.console header{height:76px;padding:0 18px;flex-wrap:wrap}.brand{font-size:24px}.brand small{font-size:6px}.menu{display:flex;gap:7px;font-size:18px}.menu span{font-size:11px;align-self:center}.account{width:100%;padding:12px 0;background:#11151c;justify-content:space-between;font-size:10px;z-index:5}.body{padding-top:38px;display:block}aside{display:none;width:100%;min-height:0;padding:18px;border-right:0;border-bottom:1px solid #333b48}aside.open{display:block}aside>p,.side-note{display:none}aside>button{padding:12px;margin:0}.heading{align-items:flex-start;flex-direction:column;margin-bottom:22px}main{width:100%;padding:22px 16px}h1{font-size:28px}.heading p{font-size:11px}.metrics{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.metrics .card{padding:16px}.metrics strong{font-size:25px}.metrics small{font-size:9px}.card{padding:17px}.card-title{align-items:flex-start}footer{line-height:1.8;flex-direction:column}.pagination{font-size:9px}.eyebrow{font-size:8px}th,td{min-width:100px;padding:12px 9px}dialog{padding:20px}}
</style>
